function reserveStudio(ledger, request, catalog) {
  // Existing IDs must retain the ledger's replay, conflict and cancellation rules,
  // even when current usage or the allocation has changed since the first booking.
  if (ledger.inspect(request.id)) return ledger.reserve(request);

