  assert.deepEqual(dispatch(request("extra", {units: 2})), {status: "full", id: "extra", remaining: 1});
  assert.equal(dispatch(request("iris-full", {tenant: "iris", units: 3})).status, "full");
  assert.equal(dispatch(request("iris", {tenant: "iris", units: 2})).remaining, 0);
  assert.equal(dispatch(request("unknown-full", {tenant: "rose", units: 6})).status, "full");
  assert.equal(dispatch(request("unknown", {tenant: "rose", units: 5})).remaining, 0);
  assert.equal(dispatch(request("archive-full", {service: "archive"})).status, "full");
